namespace Tests.System.Reactive.Shared;

/// <summary>
/// Describes <c>Seq.FromEvent(addHandler, removeHandler[, scheduler])</c> over an event of any
/// delegate type with one argument.
/// </summary>
/// <typeparam name="TDelegate">The delegate type of the event to convert.</typeparam>
/// <typeparam name="TEventArgs">The type of the event data generated by the event.</typeparam>
/// <remarks>
/// Built by the <c>Seq.FromEvent</c> overloads in <c>Seq.FromEvent.cs</c>; materialized by each
/// target through <see cref="ISeqVisitor.FromEventDelegate{TDelegate, TEventArgs}(FromEventDelegateSeq{TDelegate, TEventArgs})"/>.
/// </remarks>
public sealed class FromEventDelegateSeq<TDelegate, TEventArgs>(Action<TDelegate> addHandler,
        Action<TDelegate> removeHandler, SchedulerRef? scheduler)
    : Seq<TEventArgs>
{
    /// <summary>
    /// Action that attaches the given event handler to the underlying .NET event.
    /// </summary>
    public Action<TDelegate> AddHandler => addHandler;

    /// <summary>
    /// Action that detaches the given event handler from the underlying .NET event.
    /// </summary>
    public Action<TDelegate> RemoveHandler => removeHandler;

    /// <summary>
    /// Scheduler to run the event conversion on, or null for the target's default.
    /// </summary>
    public SchedulerRef? Scheduler => scheduler;

    /// <inheritdoc/>
    protected override Realized<Seq<TEventArgs>> AcceptCore(ISeqVisitor visitor) =>
        visitor.FromEventDelegate(this);

    /// <inheritdoc/>
    public override string ToString() =>
        scheduler is null
            ? "Seq.FromEvent(addHandler, removeHandler)"
            : $"Seq.FromEvent(addHandler, removeHandler, {scheduler})";
}
